// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// ListExerciseMaxes The 1RM history of all the user's exercises, newest first per exercise.
	// (GET /exercise-maxes)
	ListExerciseMaxes(ctx context.Context, request ListExerciseMaxesRequestObject) (ListExerciseMaxesResponseObject, error)

	// (DELETE /exercise-maxes/{id})
	DeleteExerciseMax(ctx context.Context, request DeleteExerciseMaxRequestObject) (DeleteExerciseMaxResponseObject, error)
	// AddExerciseMax Add a 1RM to an exercise's history; the newest is the current max.
	// (POST /exercises/{id}/maxes)
	AddExerciseMax(ctx context.Context, request AddExerciseMaxRequestObject) (AddExerciseMaxResponseObject, error)
	// ExerciseStats The exercises done in workouts, most often first, with their rating.
	// (GET /stats/exercises)
	ExerciseStats(ctx context.Context, request ExerciseStatsRequestObject) (ExerciseStatsResponseObject, error)
	// GetWeek The tracker's week of the chosen active training (else the first).
	// (GET /week)
	GetWeek(ctx context.Context, request GetWeekRequestObject) (GetWeekResponseObject, error)
	// ListWorkouts The workouts finished in [from, to) (at most a year), newest first.
	// (GET /workouts)
	ListWorkouts(ctx context.Context, request ListWorkoutsRequestObject) (ListWorkoutsResponseObject, error)
	// StartWorkout Start a workout of a slot of the week plan.
	// (POST /workouts)
	StartWorkout(ctx context.Context, request StartWorkoutRequestObject) (StartWorkoutResponseObject, error)
	// DeleteWorkout Discard a workout in progress or remove a finished one.
	// (DELETE /workouts/{id})
	DeleteWorkout(ctx context.Context, request DeleteWorkoutRequestObject) (DeleteWorkoutResponseObject, error)

	// (GET /workouts/{id})
	GetWorkout(ctx context.Context, request GetWorkoutRequestObject) (GetWorkoutResponseObject, error)
	// FinishWorkout Finish a workout (a finished one only gets the notes), optionally dated to another day.
	// (POST /workouts/{id}/finish)
	FinishWorkout(ctx context.Context, request FinishWorkoutRequestObject) (FinishWorkoutResponseObject, error)
	// LogResult Log the score of a WOD block, or correct the one logged for it.
	// (PUT /workouts/{id}/results)
	LogResult(ctx context.Context, request LogResultRequestObject) (LogResultResponseObject, error)

	// (DELETE /workouts/{id}/results/{resultID})
	DeleteResult(ctx context.Context, request DeleteResultRequestObject) (DeleteResultResponseObject, error)
	// LogSet Log a set, or correct the one logged at the same place.
	// (PUT /workouts/{id}/sets)
	LogSet(ctx context.Context, request LogSetRequestObject) (LogSetResponseObject, error)

	// (DELETE /workouts/{id}/sets/{setID})
	DeleteSet(ctx context.Context, request DeleteSetRequestObject) (DeleteSetResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

